-- ============================================================
-- Migration: resize_embedding_vector_1024
--
-- Purpose:
--   Switch the embedding column from vector(1536) [OpenAI/mock]
--   to vector(1024) [Ollama BGE-M3].
--
-- Strategy (safe — no cast, no data loss on non-embedding fields):
--   Step 1: Clear all derived embedding fields for existing chunks.
--           The previous vectors were generated by mock/OpenAI and
--           are NOT valid BGE-M3 embeddings. They must be discarded.
--           All other chunk data (content, contentHash, sectionTitle,
--           pageStart, pageEnd, metadata, etc.) is fully preserved.
--
--   Step 2: Drop the old vector(1536) column.
--
--   Step 3: Add the new vector(1024) column.
--
-- After this migration, run:
--   POST /api/documents/:id/embed
-- to regenerate embeddings using Ollama + BGE-M3.
-- ============================================================

-- Step 1: Clear stale OpenAI/mock embedding data from all chunks
UPDATE "document_chunks"
SET
  "embedding"           = NULL,
  "embeddingProvider"   = NULL,
  "embeddingModel"      = NULL,
  "embeddedContentHash" = NULL,
  "embeddedAt"          = NULL;

-- Step 2: Drop old 1536-dimensional column
ALTER TABLE "document_chunks" DROP COLUMN IF EXISTS "embedding";

-- Step 3: Add new 1024-dimensional column for BGE-M3
ALTER TABLE "document_chunks" ADD COLUMN "embedding" vector(1024);

-- ============================================================
-- Verification query (run manually after migration):
--
-- SELECT extname, extversion FROM pg_extension WHERE extname = 'vector';
--
